DO $$ DECLARE f text;BEGIN SELECT pg_get_functiondef('public.task_blocker_track()'::regprocedure) INTO f;f:=replace(f,'IF NEW.status=''waiting_client'' THEN NEW.blocker_reason:=''Waiting on client approval'';END IF;','IF NEW.status=''waiting_client'' THEN IF kind=''recurring'' THEN NEW.blocker_reason:=''Waiting on client approval'';ELSIF NEW.requires_client_approval THEN NEW.blocker_reason:=''Waiting on client approval'';ELSE NEW.blocker_reason:=coalesce(NEW.blocker_reason,''Other blocker'');END IF;END IF;');f:=replace(f,'IF active_block AND NEW.blocked_since IS NULL THEN NEW.blocked_since:=now();END IF;','IF active_block AND NEW.blocked_since IS NULL THEN IF kind=''launch'' THEN SELECT coalesce(NEW.client_approval_requested_at,max(a.created_at)) INTO NEW.blocked_since FROM task_activity a WHERE a.task_id=NEW.id AND a.to_status IN(''blocked'',''waiting_client''); END IF; NEW.blocked_since:=coalesce(NEW.blocked_since,now());END IF;');EXECUTE f;END $$;
UPDATE public.client_tasks t SET blocked_since=coalesce(t.client_approval_requested_at,a.since),blocker_reason=CASE WHEN t.status='waiting_client' AND t.requires_client_approval THEN 'Waiting on client approval' ELSE coalesce(t.blocker_reason,'Other blocker') END FROM (SELECT task_id,max(created_at) since FROM public.task_activity WHERE to_status IN('blocked','waiting_client') GROUP BY task_id) a WHERE t.id=a.task_id AND t.blocked_since IS NULL AND t.status IN('blocked','waiting_client');